BEGIN;
-- Google libphonenumber mobile metadata, retrieved 2026-11-24
-- Saudi compatibility remains 5 + eight digits; no existing brand or phone is rewritten
-- FOUNDATION START
ALTER TABLE public.cafes DROP CONSTRAINT cafes_phone_country_check;
ALTER TABLE public.cafes ADD CONSTRAINT cafes_phone_country_check
  CHECK(phone_country IN ('SA','AE','BH','KW','OM','QA','YE','JO','PS','LB','SY','IQ','EG','SD','LY','TN','DZ','MA','MR','SO','DJ','KM')) NOT VALID;
ALTER TABLE public.cafes VALIDATE CONSTRAINT cafes_phone_country_check;

CREATE FUNCTION brand_phone_private.country_rules()
RETURNS TABLE(code text,calling_code text,national_prefix text,mobile_pattern text)
LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path='' AS $rules$
  VALUES
    ('SA','966','0','5[0-9]{8}'),
    ('AE','971','0','5[02-68][0-9]{7}'),
    ('BH','973',NULL::text,'(?:3(?:[0-79][0-9]|8[0-57-9])[0-9]|6(?:3(?:00|33|6[16])|441|6(?:3[03-9]|[69][0-9]|7[0-689])))[0-9]{4}'),
    ('KW','965',NULL::text,'(?:41[0-9][0-9]|5(?:(?:[05][0-9]|1[0-7]|6[56])[0-9]|2(?:22|5[25])|7(?:55|77)|88[58]|999)|6(?:(?:0[034679]|5[015-9]|6[0-9])[0-9]|1(?:00|11|6[16])|2[26]2|3[36]3|4[46]4|7(?:0[013-9]|[67][0-9])|8[68]8|9(?:[069][0-9]|3[039]))|9(?:(?:[04679][0-9]|8[057-9])[0-9]|1(?:00|1[01]|99)|2(?:00|2[0-9])|3(?:00|3[03])|5(?:00|5[0-9])))[0-9]{4}'),
    ('OM','968',NULL::text,'(?:1505|90[1-9][0-9])[0-9]{4}|(?:7[124-9]|9[1-9])[0-9]{6}'),
    ('QA','974',NULL::text,'[35-7][0-9]{7}'),
    ('YE','967','0','7[0-378][0-9]{7}'),
    ('JO','962','0','(?:427|7(?:11|[29][0-9]|[78][0-25-9]))[0-9]{6}'),
    ('PS','970','0','5[69][0-9]{7}'),
    ('LB','961','0','(?:(?:3|81)[0-9]|7(?:[01][0-9]|6[013-9]|8[7-9]|9[0-4]))[0-9]{5}'),
    ('SY','963','0','(?:50|9[03-689])[0-9]{7}'),
    ('IQ','964','0','7[3-9][0-9]{8}'),
    ('EG','20','0','1[0-25][0-9]{8}'),
    ('SD','249','0','(?:1[0-2]|9[0-3569])[0-9]{7}'),
    ('LY','218','0','9[1-6][0-9]{7}'),
    ('TN','216',NULL::text,'3(?:001|[12]40)[0-9]{4}|(?:(?:[259][0-9]|4[0-8])[0-9]|3(?:1[1-35]|6[0-4]|91))[0-9]{5}'),
    ('DZ','213','0','5(?:4[0-29]|6[0-5])[0-9]{6}|(?:55|6[0-9]|7[7-9])[0-9]{7}'),
    ('MA','212','0','(?:6(?:[0-79][0-9]|8[0-247-9])|7(?:[016-8][0-9]|2[0-8]|3[01]|5[0-5]))[0-9]{6}'),
    ('MR','222',NULL::text,'[2-4][0-46-9][0-9]{6}'),
    ('SO','252','0','(?:(?:15|(?:3[59]|4[89]|6[0-9]|7[0-35-9]|8[08])[0-9]|9(?:0[0-9]|[2-9]))[0-9]|2(?:4[0-9]|8))[0-9]{5}|(?:[67][0-9][0-9]|904)[0-9]{5}'),
    ('DJ','253',NULL::text,'77[0-9]{6}'),
    ('KM','269',NULL::text,'[34][0-9]{6}')
$rules$;

-- A country can be inferred from a valid full international number only
CREATE FUNCTION brand_phone_private.country_for_phone(p_value text)
RETURNS text LANGUAGE sql IMMUTABLE STRICT SECURITY INVOKER SET search_path='' AS $phone$
  SELECT r.code FROM brand_phone_private.country_rules() r
  WHERE p_value ~ ('^'||r.calling_code||'(?:'||r.mobile_pattern||')$') LIMIT 1
$phone$;

CREATE FUNCTION brand_phone_private.normalize_country(p_country text,p_value text,p_allow_other_country boolean DEFAULT false)
RETURNS text LANGUAGE plpgsql IMMUTABLE STRICT SECURITY INVOKER SET search_path='' AS $phone$
DECLARE v text; r record; national text; international boolean; digits text;
BEGIN
  IF length(p_value)>64 OR NOT EXISTS(SELECT 1 FROM brand_phone_private.country_rules() WHERE code=p_country) THEN RETURN NULL; END IF;
  v:=regexp_replace(translate(btrim(p_value),'٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹','01234567890123456789'),'[[:space:]()-]','','g');
  v:=translate(v,chr(1564)||chr(8203)||chr(8204)||chr(8205)||chr(8206)||chr(8207)||chr(8234)||chr(8235)||chr(8236)||chr(8237)||chr(8238)||chr(8288)||chr(8294)||chr(8295)||chr(8296)||chr(8297)||chr(65279),'');
  IF v !~ '^\+?[0-9]+$' THEN RETURN NULL; END IF;
  international:=left(v,1)='+' OR left(v,2)='00';
  digits:=CASE WHEN left(v,1)='+' THEN substr(v,2) WHEN left(v,2)='00' THEN substr(v,3) ELSE v END;
  FOR r IN SELECT * FROM brand_phone_private.country_rules() ORDER BY length(calling_code) DESC LOOP
    IF left(digits,length(r.calling_code))<>r.calling_code THEN CONTINUE; END IF;
    national:=substr(digits,length(r.calling_code)+1);
    IF r.national_prefix='0' AND left(national,1)='0' THEN national:=substr(national,2); END IF;
    IF national ~ ('^(?:'||r.mobile_pattern||')$') THEN
      IF NOT p_allow_other_country AND r.code<>p_country THEN RETURN NULL; END IF;
      RETURN r.calling_code||national;
    END IF;
  END LOOP;
  IF international THEN RETURN NULL; END IF;
  SELECT * INTO r FROM brand_phone_private.country_rules() WHERE code=p_country;
  national:=v;
  IF r.national_prefix='0' AND left(national,1)='0' THEN national:=substr(national,2); END IF;
  IF national ~ ('^(?:'||r.mobile_pattern||')$') THEN RETURN r.calling_code||national; END IF;
  RETURN NULL;
END $phone$;

CREATE OR REPLACE FUNCTION brand_phone_private.normalize(p_cafe uuid,p_value text)
RETURNS text LANGUAGE sql STABLE STRICT SECURITY INVOKER SET search_path='' AS $phone$
  SELECT brand_phone_private.normalize_country(c.phone_country,p_value,false) FROM public.cafes c WHERE c.id=p_cafe
$phone$;

CREATE FUNCTION brand_phone_private.staff_normalize(p_cafe uuid,p_value text)
RETURNS text LANGUAGE sql STABLE STRICT SECURITY INVOKER SET search_path='' AS $phone$
  SELECT brand_phone_private.normalize_country(c.phone_country,p_value,true) FROM public.cafes c WHERE c.id=p_cafe
$phone$;
CREATE FUNCTION brand_phone_private.staff_canonical(p_cafe uuid,p_value text)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $phone$
  SELECT coalesce(brand_phone_private.staff_normalize(p_cafe,p_value)=p_value,false)
$phone$;
REVOKE ALL ON FUNCTION brand_phone_private.country_rules(),brand_phone_private.country_for_phone(text),brand_phone_private.normalize_country(text,text,boolean),brand_phone_private.staff_normalize(uuid,text),brand_phone_private.staff_canonical(uuid,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION brand_phone_private.country_rules(),brand_phone_private.country_for_phone(text),brand_phone_private.normalize_country(text,text,boolean),brand_phone_private.staff_normalize(uuid,text),brand_phone_private.staff_canonical(uuid,text) TO service_role;
-- FOUNDATION END

-- Preserve each routine's current authorization, retries, locking and privileges
CREATE FUNCTION pg_temp.patch_arab_phone(fn regprocedure,baselines text[],edits text[][]) RETURNS void
LANGUAGE plpgsql AS $patch$
DECLARE source text; signature text; pair text[];
BEGIN
  SELECT replace(pg_get_functiondef(oid),chr(13),''),md5(replace(prosrc,chr(13),'')) INTO STRICT source,signature FROM pg_proc WHERE oid=fn;
  IF NOT signature=ANY(baselines) THEN RAISE EXCEPTION 'Arab phone prerequisite changed for %',fn; END IF;
  FOREACH pair SLICE 1 IN ARRAY edits LOOP
    IF position(pair[1] IN source)=0 THEN RAISE EXCEPTION 'Arab phone anchor missing in %',fn; END IF;
    source:=replace(source,pair[1],pair[2]);
  END LOOP;
  EXECUTE source;
END $patch$;

